from pathlib import Path
import json,shutil,html,sys
root=Path(__file__).resolve().parents[1]
dest=root/"design/phase16"
out=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else root/"output/phase16"
for p in [dest,out]:p.mkdir(parents=True,exist_ok=True)
receipt=json.loads((root/"evidence/real-case/reviewed-memory-receipt.json").read_text())["data"]
accepted=json.loads((root/"evidence/phase14/public-reviewed-case/acceptance.json").read_text())
current=accepted["checks"]["recurrenceTransaction"]["data"]["transaction"]
record=receipt["record"];proof=receipt["proof"];source=record["digest"];second=current["digest"];blob=proof["blobId"]
evidence=record["evidenceUrl"]
data={"provenance":"Recorded approved case; static composition target, not live integration","source":source,"recurrence":second,"reviewer":record["reviewer"],"diagnosis":record["diagnosis"],"procedure":record["resolutionSteps"],"blob":blob,"job":proof["jobId"],"namespace":proof["namespace"],"evidenceUrl":evidence,"evidenceHash":record["validatedEvidence"]["evidenceSha256"],"checkpoint":current["checkpoint"],"package":record["packageId"]}
(dest/"case-data.json").write_text(json.dumps(data,indent=2)+"\n")
